const input = $input.first().json;
const data = input.body || input;

const name = (data.name || '').trim();
let phone = (data.phone || '').trim().replace(/[\s-]/g, '');
const email = (data.email || '').trim().toLowerCase();
const service = (data.service || 'Consultation').trim();
const source = (data.source || 'website').trim();
const timezone = (data.timezone || 'Asia/Karachi').trim();
const durationMinutes = Number(data.duration_minutes || 45);

const errors = [];
if (!name || name.length < 2) errors.push('Valid customer name is required (min 2 chars).');
if (!/^\+?[1-9]\d{7,14}$/.test(phone)) errors.push('Valid phone number in E.164 format is required.');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errors.push('Valid email address is required.');
if (!data.requested_start) errors.push('requested_start timestamp is required.');

let startDate, endDate;
if (data.requested_start) {
  startDate = new Date(data.requested_start);
  if (isNaN(startDate.getTime())) {
    errors.push('requested_start must be a valid ISO 8601 date.');
  } else if (startDate.getTime() <= Date.now() + 300000) {
    errors.push('requested_start must be at least 5 minutes in the future.');
  } else {
    endDate = new Date(startDate.getTime() + durationMinutes * 60000);
  }
}

if (!phone.startsWith('+')) {
  phone = '+' + phone;
}

const bookingId = 'BK-' + Date.now() + '-' + Math.random().toString(36).substring(2, 7).toUpperCase();
const rescheduleUrl = 'https://realestateleadmanagement-n8n-b138c4-13-203-193-36.sslip.io/webhook/appointment-lifecycle?booking_id=' + bookingId + '&action=reschedule';

return [{
  json: {
    is_valid: errors.length === 0,
    errors: errors,
    error_message: errors.join(' '),
    booking_id: bookingId,
    customer_name: name,
    phone_e164: phone,
    email: email,
    service: service,
    source: source,
    timezone: timezone,
    duration_minutes: durationMinutes,
    requested_start: startDate ? startDate.toISOString() : null,
    requested_end: endDate ? endDate.toISOString() : null,
    reschedule_url: rescheduleUrl
  }
}];

const booking = $('Normalize & Validate').first().json;
const items = $input.all();

let isConflict = false;
let conflictEvents = [];

for (const item of items) {
  const evt = item.json;
  if (evt && evt.id && evt.status !== 'cancelled' && evt.summary && !evt.error) {
    isConflict = true;
    conflictEvents.push({ id: evt.id, summary: evt.summary });
  }
}

return [{
  json: {
    ...booking,
    is_slot_available: !isConflict,
    conflict_count: conflictEvents.length,
    conflict_events: conflictEvents
  }
}];
